test('invoiceTotals VAT is sum of rounded line VATs', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 100, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Vat = lineVAT(invoice.lines[0]);
  const line2Vat = lineVAT(invoice.lines[1]);
  const line3Vat = lineVAT(invoice.lines[2]);
  assert.equal(totals.vat, line1Vat + line2Vat + line3Vat);
  assert.equal(totals.vat, 63);
});

